import subprocess
from flask import request, jsonify

@app.route('/ping')
def ping():
    host = request.args.get('host', '')
    result = subprocess.run(
        ['ping', '-c', '1', host],
        capture_output=True,
        text=True,
        timeout=5
    )
    return jsonify({'output': result.stdout})

